// src/components/BlockLibraryPanel.tsx
"use client";

import { useMemo } from "react";
import { allUnits } from "@/data/units";
import type { MetalType, UnitCategory, UnitDefinition } from "@/types/units";

const CATEGORIES: UnitCategory[] = [
  "Feed & Tailings",
  "Comminution",
  "Flotation",
  "Dewatering",
];

interface BlockLibraryPanelProps {
  selectedMetal: MetalType;
}

export function BlockLibraryPanel({ selectedMetal }: BlockLibraryPanelProps) {
  const unitsByCategory = useMemo(() => {
    const filtered = allUnits.filter((u) => u.metal === selectedMetal);
    const map: Record<UnitCategory, UnitDefinition[]> = {
      "Feed & Tailings": [],
      Comminution: [],
      Flotation: [],
      Dewatering: [],
    };
    filtered.forEach((u) => map[u.category].push(u));
    return map;
  }, [selectedMetal]);

  const handleDragStart = (
    event: React.DragEvent<HTMLDivElement>,
    unit: UnitDefinition
  ) => {
    // این دیتا بعداً در T11 در Canvas استفاده می‌شود
    event.dataTransfer.setData(
      "application/json",
      JSON.stringify({
        type: unit.id,
        parameters: unit.defaultParameters,
      })
    );
    event.dataTransfer.effectAllowed = "move";
  };

  return (
    <aside className="w-64 border-r p-4 bg-white flex flex-col gap-3">
      <div className="flex items-center justify-between mb-2">
        <h2 className="font-semibold text-sm">Block Library</h2>
        <span className="text-xs rounded-full bg-slate-100 px-2 py-0.5">
          {selectedMetal === "Cu" ? "Copper" : "Zinc"}
        </span>
      </div>

      <div className="flex flex-col gap-3 overflow-auto">
        {CATEGORIES.map((cat) => {
          const units = unitsByCategory[cat];
          if (!units.length) return null;
          return (
            <div key={cat}>
              <div className="text-xs font-semibold text-slate-500 mb-1 uppercase tracking-wide">
                {cat}
              </div>
              <div className="flex flex-col gap-1">
                {units.map((unit) => (
                    <div
                    key={unit.id}
                    draggable
                    onDragStart={(e) => handleDragStart(e, unit)}
                    className="flex items-center gap-3 rounded-md border px-2 py-2 text-xs cursor-move bg-white hover:bg-slate-50 transition"
                  >
                    <div className="h-10 w-10 flex items-center justify-center rounded-md bg-slate-100 overflow-hidden">
                      {unit.icon ? (
                        <img
                          src={`/icons/${unit.icon}.png`} // یا .svg اگر فایل‌هات svg هستن
                          alt={unit.name}
                          width={40}
                          height={40}
                          style={{ objectFit: "contain" }}
                        />
                      ) : (
                        <span className="text-[10px] font-semibold">{unit.metal}</span>
                      )}
                    </div>

                    <div className="flex flex-col">
                      <span className="font-medium text-xs">{unit.name}</span>
                      <span className="text-[10px] text-slate-500">
                        Rec: {unit.defaultParameters.recovery} • Split:{" "}
                        {unit.defaultParameters.split_ratio}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>
    </aside>
  );
}
